const fl = flash.get(`${row.id}|${field}`);
if (fl && Date.now() - fl.t < FLASH_MS) {
  const k = 1 - (Date.now() - fl.t) / FLASH_MS; // 1 -> 0
  const c = fl.up ? UP : DOWN;
  pill.style.background = `color-mix(in srgb, ${c} ${Math.round(26 * k)}%, ${SURFACE})`;
}

function onFacetPointerDown(e) {
  const cell = e.target.closest('[data-mp-group]');
  const group = cell?.dataset.mpGroup;
  if (!group) return;
  collapsed.has(group) ? collapsed.delete(group) : collapsed.add(group);
  renderStructure();
}
gridMount.addEventListener('pointerdown', onFacetPointerDown);

